/bin/zsh -lc "python3 - <<'PY'
import json
from collections import Counter
from pathlib import Path
source=json.loads(Path('declarations.json').read_text())
result=json.loads(Path('out/declarations.json').read_text())
passages={json.loads(line)['id'] for line in Path('passages.jsonl').read_text().splitlines()}
assert Counter(r['id'] for r in result)==Counter(r['id'] for r in source)
assert all(n==1 for n in Counter(r['id'] for r in result).values())
for r in result:
 assert set(r)=={'id','kind','matches','tension','notes'}
 assert r['kind'] in {'syntax_definition','representation','derived_property','operational_model','unclear'}
 assert isinstance(r['notes'],str)
 assert isinstance(r['matches'],list)
 for m in r['matches']:
  assert set(m)=={'passage','relation'}
  assert m['passage'] in passages
  assert m['relation'] in {'defines','uses','version_difference'}
 if r['tension'] is not None:
  assert set(r['tension'])=={'passages','description'}
  assert r['tension']['passages'] and all(p in passages for p in r['tension']['passages'])
  assert isinstance(r['tension']['description'],str)
print('PASS: valid JSON, exactly 298 unique declaration records, valid schema, all match and tension passage IDs exist.')
print('Deliverable:',Path('out/declarations.json').stat().st_size,'bytes')
print('Output files:',', '.join(str(p) for p in Path('out').iterdir()))
PY"
